// searches said, and stamps fetched_at, which only moves on. A merged item keeps its
// state, since nothing comes back from a merge. Nothing changes when none is stored. The
// refresh applies the item writes stored while it fetched after this (see order.go), so
// it needs no guard of SetRefStateBefore's.
func (q *Queries) SetRefState(ctx context.Context, arg SetRefStateParams) error {
	_, err := q.db.ExecContext(ctx, setRefState,
		arg.State,
		arg.ClosedAt,
		arg.FetchedAt,
		arg.Number,
		arg.Owner,
		arg.Name,
	)
	return err
}

const setRefStateBefore = `-- name: SetRefStateBefore :many
UPDATE items SET
    state = ?1,
    closed_at = ?2,
    fetched_at = CASE WHEN items.fetched_at < ?3 THEN ?3 ELSE items.fetched_at END
WHERE number = ?4
  AND repo_id IN (SELECT id FROM repos WHERE owner = ?5 AND name = ?6)
  AND items.state <> 'MERGED'
  AND items.fetched_at < ?7
RETURNING id
`

type SetRefStateBeforeParams struct {
	State      string
	ClosedAt   *time.Time
	FetchedAt  time.Time
	Number     int64
	Owner      string
	Name       string
	ReadBefore time.Time
}

// SetRefStateBefore is SetRefState for a read that went out at read_before outside a whole
// refresh (a watch pass's searches, another service's read): an item stored at or after
// read_before keeps what that newer read stored. It returns the ids of the items it wrote,
// which the write order records (see order.go).
func (q *Queries) SetRefStateBefore(ctx context.Context, arg SetRefStateBeforeParams) ([]int64, error) {
	rows, err := q.db.QueryContext(ctx, setRefStateBefore,
		arg.State,
		arg.ClosedAt,
		arg.FetchedAt,
		arg.Number,
		arg.Owner,
		arg.Name,
		arg.ReadBefore,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []int64{}
	for rows.Next() {
		var id int64
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const upsertChecks = `-- name: UpsertChecks :exec
INSERT INTO item_checks (item_id, head_oid, checks, complete, settled_at, fetched_at)
VALUES (?, ?, ?, ?, ?, ?)
ON CONFLICT (item_id) DO UPDATE SET
    head_oid = excluded.head_oid,
    checks = excluded.checks,
    complete = excluded.complete,
    settled_at = excluded.settled_at,
    fetched_at = excluded.fetched_at
`

type UpsertChecksParams struct {
	ItemID    int64
	HeadOID   string
	Checks    string
	Complete  bool
	SettledAt *time.Time
	FetchedAt time.Time
}

// UpsertChecks stores a pull request's checks on one head commit, replacing what was
// stored before.
func (q *Queries) UpsertChecks(ctx context.Context, arg UpsertChecksParams) error {
	_, err := q.db.ExecContext(ctx, upsertChecks,
		arg.ItemID,
		arg.HeadOID,
		arg.Checks,
		arg.Complete,
		arg.SettledAt,
		arg.FetchedAt,
	)
	return err
}

const upsertWatch = `-- name: UpsertWatch :exec
INSERT INTO item_watches (watch_key, item_id, follow, seen_at, stale)
VALUES (?, ?, ?, ?, 0)
ON CONFLICT (watch_key, item_id) DO UPDATE SET
    follow = excluded.follow,
    seen_at = excluded.seen_at,
    stale = 0
`

type UpsertWatchParams struct {
	WatchKey string
	ItemID   int64
	Follow   bool
	SeenAt   time.Time
}

// UpsertWatch records that the search with watch_key returned the item with item_id now:
// the row is fresh again, and follow is as the routines that share the search ask.
func (q *Queries) UpsertWatch(ctx context.Context, arg UpsertWatchParams) error {
	_, err := q.db.ExecContext(ctx, upsertWatch,
		arg.WatchKey,
		arg.ItemID,
		arg.Follow,
		arg.SeenAt,
	)
	return err
}

const upsertWatchedItem = `-- name: UpsertWatchedItem :one
INSERT INTO items (
    account_id, repo_id, kind, number, node_id, title, url, author_login, author_type, author_association,
    is_cross_repository, is_draft, head_ref, item_created_at, item_updated_at, fetched_at, state, closed_at,
    seen_activity_at
) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
ON CONFLICT (account_id, repo_id, kind, number) DO UPDATE SET
    node_id = excluded.node_id,
    title = excluded.title,
    url = excluded.url,
    author_login = excluded.author_login,
    author_type = excluded.author_type,
    author_association = excluded.author_association,
    is_cross_repository = excluded.is_cross_repository,
    is_draft = excluded.is_draft,
    head_ref = excluded.head_ref,
    item_created_at = excluded.item_created_at,
    item_updated_at = excluded.item_updated_at,
    state = CASE WHEN excluded.state = '' OR items.state = 'MERGED' THEN items.state ELSE excluded.state END,
    closed_at = CASE WHEN excluded.state = '' OR items.state = 'MERGED' THEN items.closed_at ELSE excluded.closed_at END,
    fetched_at = excluded.fetched_at
RETURNING id
`

type UpsertWatchedItemParams struct {
	AccountID         int64
	RepoID            int64
	Kind              string
	Number            int64
	NodeID            string
	Title             string
	URL               string
	AuthorLogin       string
	AuthorType        string
	AuthorAssociation string
	IsCrossRepository bool
	IsDraft           bool
	HeadRef           string
	ItemCreatedAt     time.Time
	ItemUpdatedAt     time.Time
	FetchedAt         time.Time
	State             string
	ClosedAt          *time.Time
	SeenActivityAt    *time.Time
}

// UpsertWatchedItem stores what a routine's search says about an item, and returns its id.
// A new item is in no list; one already stored for the same account, repository, kind,
// and number has what GitHub says rewritten, its state included but over a merge, which
// nothing comes back from, and keeps its lists, the times it arrived in them, and the
// lists the user left, which only the inbox's own searches and reads change. A new item
// counts as seen at its activity (seen_activity_at), since a watched item isn't news; one
// already stored keeps what the user last saw.
func (q *Queries) UpsertWatchedItem(ctx context.Context, arg UpsertWatchedItemParams) (int64, error) {
	row := q.db.QueryRowContext(ctx, upsertWatchedItem,
		arg.AccountID,
		arg.RepoID,
		arg.Kind,
		arg.Number,
		arg.NodeID,
		arg.Title,
		arg.URL,
		arg.AuthorLogin,
		arg.AuthorType,
		arg.AuthorAssociation,
		arg.IsCrossRepository,
		arg.IsDraft,
		arg.HeadRef,
		arg.ItemCreatedAt,
		arg.ItemUpdatedAt,
		arg.FetchedAt,
		arg.State,
		arg.ClosedAt,
		arg.SeenActivityAt,
	)
	var id int64
	err := row.Scan(&id)
	return id, err
}
